window.PYFILES = {"ch1_adjust": "import pandas as pd\n\n# 一只虚构股票的 6 个交易日原始(不复权)收盘价 —— 教学用模拟数据\nraw = pd.DataFrame({\n    \"date\": pd.to_datetime([\"2024-06-03\", \"2024-06-04\", \"2024-06-05\",\n                            \"2024-06-06\", \"2024-06-07\", \"2024-06-11\"]),\n    \"close\": [20.0, 20.4, 10.0, 10.3, 10.1, 10.5],\n})\n# 公司行为(corporate action)表:6 月 5 日除权除息,每股派现 0.4 元,每 1 股送转 1 股\nactions = pd.DataFrame({\n    \"date\": pd.to_datetime([\"2024-06-05\"]),\n    \"cash_div\": [0.4],     # 每股现金分红(元)\n    \"split\": [1.0],        # 每股送转股数:10 送 10 即每股送 1 股\n})\n\ndf = raw.merge(actions, on=\"date\", how=\"left\").fillna({\"cash_div\": 0.0, \"split\": 0.0})\ndf[\"prev_close\"] = df[\"close\"].shift(1)                       # 前一交易日收盘价\n# 除权参考价 = (前收盘 − 每股派现) / (1 + 每股送转)\ndf[\"ref_price\"] = (df[\"prev_close\"] - df[\"cash_div\"]) / (1 + df[\"split\"])\n# 单日复权因子:除权日 = 前收盘 / 除权参考价,其它日子 = 1\ndf[\"step\"] = (df[\"prev_close\"] / df[\"ref_price\"]).where(df[\"cash_div\"] + df[\"split\"] > 0, 1.0)\ndf[\"adj_factor\"] = df[\"step\"].cumprod()                        # 累计复权因子(从第一天起连乘)\ndf[\"hfq\"] = df[\"close\"] * df[\"adj_factor\"]                     # 后复权价:第一天价格不变\ndf[\"qfq\"] = df[\"hfq\"] / df[\"adj_factor\"].iloc[-1]              # 前复权价:最后一天价格不变\n\ndf[\"ret_raw\"] = df[\"close\"].pct_change()                       # 用原始价算的“收益”(错的)\ndf[\"ret_adj\"] = df[\"hfq\"].pct_change()                         # 用复权价算的收益(对的)\npd.set_option(\"display.width\", 120)\ndf[\"date\"] = df[\"date\"].dt.strftime(\"%m-%d\")                     # 只显示月-日,便于阅读\nprint(df[[\"date\", \"close\", \"ref_price\", \"adj_factor\", \"hfq\", \"qfq\", \"ret_raw\", \"ret_adj\"]].round(4).to_string(index=False))\n", "ch1_parquet": "import os, tempfile, time\nimport numpy as np\nimport pandas as pd\n\nrng = np.random.default_rng(0)\ndates = pd.bdate_range(\"2020-01-01\", \"2023-12-29\")          # 约 1000 个工作日\ncodes = [f\"S{i:04d}\" for i in range(500)]                    # 500 只虚构股票\nidx = pd.MultiIndex.from_product([dates, codes], names=[\"date\", \"code\"])\npanel = pd.DataFrame({\n    \"close\": rng.lognormal(3, 0.5, len(idx)).astype(\"float32\"),   # 模拟数据,仅用来测存储\n    \"volume\": rng.integers(0, 10**7, len(idx)).astype(\"int64\"),\n}, index=idx).reset_index()\npanel[\"year\"] = panel[\"date\"].dt.year                        # 用来分区的列\n\nroot = tempfile.mkdtemp()\ncsv_path = os.path.join(root, \"panel.csv\")\npq_dir = os.path.join(root, \"panel_pq\")\n\npanel.to_csv(csv_path, index=False)                                  # 文本格式\npanel.to_parquet(pq_dir, partition_cols=[\"year\"], index=False)       # 按年分区的 parquet 数据集\n\ndef size(p):\n    if os.path.isfile(p):\n        return os.path.getsize(p)\n    return sum(os.path.getsize(os.path.join(d, f)) for d, _, fs in os.walk(p) for f in fs)\n\nprint(f\"行数: {len(panel):,}\")\nprint(f\"CSV 体积: {size(csv_path)/1e6:.1f} MB, Parquet 体积: {size(pq_dir)/1e6:.1f} MB\")\n\nt0 = time.perf_counter()\nsub = pd.read_parquet(pq_dir, columns=[\"date\", \"code\", \"close\"],\n                      filters=[(\"year\", \"=\", 2023), (\"code\", \"in\", [\"S0001\", \"S0002\"])])\nprint(f\"只读 2023 年 2 只股票的 close 列: {len(sub)} 行, 用时 {time.perf_counter()-t0:.2f}s\")\nprint(sub.head(3).to_string(index=False))\n", "ch1_pit": "import pandas as pd\n\n# 财报表:报告期(period)和真实公告日(ann_date)不是一回事 —— 教学用虚构数据\nfin = pd.DataFrame({\n    \"code\": [\"A\", \"A\", \"A\", \"A\"],\n    \"period\": pd.to_datetime([\"2023-12-31\", \"2024-03-31\", \"2023-12-31\", \"2024-06-30\"]),\n    \"ann_date\": pd.to_datetime([\"2024-04-20\", \"2024-04-28\", \"2024-06-15\", \"2024-08-25\"]),\n    \"net_profit\": [10.0, 3.0, 8.5, 6.2],   # 第三行:2023 年报在 6 月 15 日被“更正”为 8.5\n})\n# 每月末调仓一次,想知道“当时”能看到的最新一期净利润\nrebal = pd.to_datetime([\"2024-03-29\", \"2024-04-30\", \"2024-06-28\", \"2024-08-30\"])\n\n# ❌ 错误做法 1:按报告期对齐 —— 3 月 29 日就“看到了”4 月 20 日才公布、甚至 6 月才更正的数据\nwrong = pd.merge_asof(pd.DataFrame({\"code\": \"A\", \"date\": rebal}),\n                      fin.sort_values(\"period\"), left_on=\"date\", right_on=\"period\", by=\"code\")\n\ndef pit_latest(fin, code, asof):\n    \"\"\"point-in-time 查询:只用 asof 当天及以前已公告的记录,\n    取其中报告期最新的一期;同一报告期有多次公告时取最后一次(更正版)。\"\"\"\n    known = fin[(fin[\"code\"] == code) & (fin[\"ann_date\"] <= asof)]     # 1) 只保留当时已知的\n    if known.empty:\n        return None                                                    # 当时还没有任何财报\n    known = known.sort_values([\"period\", \"ann_date\"])                  # 2) 按报告期、公告日排序\n    return known.iloc[-1]                                              # 3) 最后一行 = 最新期的最新版本\n\n# ❌ 错误做法 2:用“今天的数据库快照”——每个报告期只保留最终修订版,丢失了更正前的数值\nsnapshot_fy23 = fin[fin[\"period\"] == \"2023-12-31\"].sort_values(\"ann_date\").iloc[-1][\"net_profit\"]\n\nrows = []\nfor d in rebal:\n    r = pit_latest(fin, \"A\", d)\n    fy23 = fin[(fin[\"period\"] == \"2023-12-31\") & (fin[\"ann_date\"] <= d)].sort_values(\"ann_date\")\n    rows.append({\"date\": d.date(),\n                 \"wrong_by_period\": wrong.loc[wrong[\"date\"] == d, \"net_profit\"].item(),\n                 \"pit_period\": None if r is None else r[\"period\"].date(),\n                 \"pit_profit\": None if r is None else r[\"net_profit\"],\n                 \"fy23_snapshot\": snapshot_fy23,                                   # 错:永远是 8.5\n                 \"fy23_pit\": fy23[\"net_profit\"].iloc[-1] if len(fy23) else None})  # 对:10.0 → 8.5\nprint(pd.DataFrame(rows).to_string(index=False))\n", "ch1_tradable": "import numpy as np\nimport pandas as pd\n\n# 模拟 5 只股票某一天的行情快照(教学用虚构数据)\nbar = pd.DataFrame({\n    \"code\":       [\"A\", \"B\", \"C\", \"D\", \"E\"],\n    \"board\":      [\"main\", \"main\", \"st\", \"gem\", \"main\"],   # 主板 / ST / 创业板\n    \"pre_close\":  [10.00, 8.00, 5.00, 30.00, 12.00],\n    \"open\":       [11.00, 7.50, 5.25, 31.00, np.nan],\n    \"high\":       [11.00, 7.90, 5.25, 36.00, np.nan],\n    \"low\":        [11.00, 7.20, 5.25, 30.50, np.nan],\n    \"close\":      [11.00, 7.20, 5.25, 36.00, np.nan],\n    \"volume\":     [1.2e5, 3.4e6, 8.0e4, 5.1e6, 0.0],\n})\n# 不同板块的涨跌幅限制(示意,具体以交易所最新规则为准)\nlimit_pct = bar[\"board\"].map({\"main\": 0.10, \"st\": 0.05, \"gem\": 0.20})\n# 涨停价/跌停价 = 前收盘 × (1 ± 限制比例),四舍五入到分\nbar[\"up_limit\"] = (bar[\"pre_close\"] * (1 + limit_pct)).round(2)\nbar[\"down_limit\"] = (bar[\"pre_close\"] * (1 - limit_pct)).round(2)\n\nbar[\"suspended\"] = bar[\"volume\"].fillna(0) <= 0                       # 停牌:无成交\nbar[\"one_word_up\"] = (bar[\"low\"] >= bar[\"up_limit\"]) & ~bar[\"suspended\"]   # 一字涨停:最低价=涨停价\nbar[\"close_at_down\"] = bar[\"close\"] <= bar[\"down_limit\"]              # 收盘跌停\n\n# 回测里的“能否成交”规则(保守版本):\nbar[\"can_buy\"] = ~bar[\"suspended\"] & ~bar[\"one_word_up\"]              # 停牌、一字涨停都买不进\nbar[\"can_sell\"] = ~bar[\"suspended\"] & ~bar[\"close_at_down\"]           # 停牌、跌停(按收盘价成交时)卖不出\nprint(bar[[\"code\", \"board\", \"pre_close\", \"close\", \"up_limit\", \"down_limit\",\n           \"suspended\", \"one_word_up\", \"can_buy\", \"can_sell\"]].to_string(index=False))\n", "ch2_combine": "import numpy as np\nimport pandas as pd\nfrom ch2_sim import make_panel\nfrom ch2_preprocess import winsorize_mad, zscore, neutralize\n\npanel = make_panel()\n\ndef clean(g, col):\n    \"\"\"去极值 → 标准化 → 中性化 → 再标准化,返回干净的因子暴露。\"\"\"\n    f = zscore(winsorize_mad(g[col]))\n    return zscore(neutralize(f, g[\"industry\"], g[\"log_mcap\"]))\n\nparts = []\nfor m, g in panel.groupby(\"month\"):\n    g = g.copy()\n    g[\"f1\"], g[\"f2\"] = clean(g, \"factor_raw\"), clean(g, \"factor2_raw\")\n    parts.append(g)\npanel = pd.concat(parts, ignore_index=True)\n\ndef rank_ic(df, col):\n    return df.groupby(\"month\").apply(lambda g: g[col].corr(g[\"fwd_ret\"], method=\"spearman\"))\n\nic1, ic2 = rank_ic(panel, \"f1\"), rank_ic(panel, \"f2\")\nprint(f\"f1 与 f2 的平均截面相关: {panel.groupby('month').apply(lambda g: g['f1'].corr(g['f2'])).mean():.2f}\")\n\n# 方法 A:等权合成\npanel[\"eq\"] = (panel[\"f1\"] + panel[\"f2\"]) / 2\n# 方法 B:按“过去 12 个月”的 ICIR 加权 —— 权重只用历史信息,避免未来函数\nicir1 = (ic1.rolling(12).mean() / ic1.rolling(12).std()).shift(1)   # shift(1):本月只能用到上月为止\nicir2 = (ic2.rolling(12).mean() / ic2.rolling(12).std()).shift(1)\nw1 = icir1.clip(lower=0) / (icir1.clip(lower=0) + icir2.clip(lower=0))  # 负的 ICIR 不给权重\npanel[\"w1\"] = panel[\"month\"].map(w1)\npanel[\"icir_w\"] = panel[\"w1\"] * panel[\"f1\"] + (1 - panel[\"w1\"]) * panel[\"f2\"]\nvalid = panel.dropna(subset=[\"icir_w\"])                                    # 前 13 个月没有足够历史\n\nfor name in [\"f1\", \"f2\", \"eq\", \"icir_w\"]:\n    r = rank_ic(valid, name)\n    print(f\"{name:7s} RankIC均值={r.mean():.4f}  ICIR={r.mean()/r.std():.3f}\")\nprint(f\"ICIR 加权中 f1 的平均权重: {w1.mean():.2f}\")\n", "ch2_ic": "import numpy as np\nimport pandas as pd\nfrom ch2_sim import make_panel\nfrom ch2_preprocess import winsorize_mad, zscore, neutralize   # 复用上一段的预处理函数\n\npanel = make_panel()\n\ndef prep(g):\n    f = zscore(winsorize_mad(g[\"factor_raw\"]))\n    g = g.copy()\n    g[\"factor\"] = zscore(neutralize(f, g[\"industry\"], g[\"log_mcap\"]))\n    return g\npanel = pd.concat([prep(g) for _, g in panel.groupby(\"month\")], ignore_index=True)\n\n# ---- 1) 每期 IC 与 RankIC ----\nby_m = panel.groupby(\"month\")\nic = by_m.apply(lambda g: g[\"factor\"].corr(g[\"fwd_ret\"]))                      # Pearson IC\nric = by_m.apply(lambda g: g[\"factor\"].corr(g[\"fwd_ret\"], method=\"spearman\"))  # 秩相关 RankIC\nicir = ric.mean() / ric.std()                                                  # 信息比率 ICIR(月度)\nt_stat = ric.mean() / (ric.std() / np.sqrt(len(ric)))                          # 均值是否显著不为 0\nprint(f\"期数={len(ric)}  IC均值={ic.mean():.4f}  RankIC均值={ric.mean():.4f}  RankIC标准差={ric.std():.4f}\")\nprint(f\"ICIR={icir:.3f}  年化ICIR≈{icir*np.sqrt(12):.2f}  t值={t_stat:.2f}  RankIC>0 占比={(ric>0).mean():.1%}\")\n\n# ---- 2) 分层(分位数)回测:每期按因子分 5 组,看各组下月平均收益 ----\npanel[\"q\"] = by_m[\"factor\"].transform(lambda s: pd.qcut(s, 5, labels=False) + 1)\nq_ret = panel.groupby([\"month\", \"q\"])[\"fwd_ret\"].mean().unstack()   # 行=月份,列=组别 1..5\nprint(\"\\n各组月均收益(%):\", (q_ret.mean() * 100).round(3).to_dict())\nls = q_ret[5] - q_ret[1]                                            # 多空组合:做多第5组、做空第1组\nprint(f\"多空月均收益={ls.mean():.4%}  年化夏普≈{ls.mean()/ls.std()*np.sqrt(12):.2f}\")\n\n# ---- 3) 换手率:第 5 组成分股每月有多少比例被换掉 ----\ntop = panel[panel[\"q\"] == 5].groupby(\"month\")[\"code\"].apply(set)\nturnover = [1 - len(a & b) / len(b) for a, b in zip(top[:-1], top[1:])]\nprint(f\"第5组平均月换手率={np.mean(turnover):.1%}\")\n\n# ---- 4) 因子衰减:用 t 月因子去预测 t+h 月收益 ----\nwide_f = panel.pivot(index=\"month\", columns=\"code\", values=\"factor\")\nwide_r = panel.pivot(index=\"month\", columns=\"code\", values=\"fwd_ret\")\nfor h in [0, 1, 2, 3, 6]:\n    ics = [wide_f.iloc[t].corr(wide_r.iloc[t + h], method=\"spearman\") for t in range(len(wide_f) - h)]\n    print(f\"滞后 {h} 期的 RankIC 均值: {np.mean(ics):.4f}\")\n", "ch2_preprocess": "import numpy as np\nimport pandas as pd\nfrom ch2_sim import make_panel\n\ndef winsorize_mad(x: pd.Series, k: float = 5.0) -> pd.Series:\n    \"\"\"MAD 去极值:把超出 中位数 ± k×1.4826×MAD 的值“拉回”到边界上。\"\"\"\n    med = x.median()\n    mad = (x - med).abs().median()            # 绝对离差的中位数\n    sigma = 1.4826 * mad                      # 正态分布下 1.4826×MAD ≈ 标准差\n    return x.clip(med - k * sigma, med + k * sigma)\n\ndef zscore(x: pd.Series) -> pd.Series:\n    \"\"\"标准化:减均值、除标准差,让不同因子处于同一量纲。\"\"\"\n    return (x - x.mean()) / x.std()\n\ndef neutralize(f: pd.Series, industry: pd.Series, log_mcap: pd.Series) -> pd.Series:\n    \"\"\"行业 + 市值中性化:对 [行业哑变量, 对数市值] 做截面回归,取残差。\"\"\"\n    X = pd.get_dummies(industry, prefix=\"ind\", dtype=float)   # 每个行业一列 0/1,相当于各行业有自己的截距\n    X[\"size\"] = zscore(log_mcap)\n    beta, *_ = np.linalg.lstsq(X.values, f.values, rcond=None)  # 最小二乘求回归系数\n    resid = f.values - X.values @ beta                          # 残差 = 因子中无法被行业/市值解释的部分\n    return pd.Series(resid, index=f.index)\n\nif __name__ == \"__main__\":                  # 被其它脚本 import 时不执行下面的演示\n    panel = make_panel()\n    cs = panel[panel[\"month\"] == panel[\"month\"].iloc[0]].copy()     # 取第一个月的截面\n\n    cs[\"f_w\"] = winsorize_mad(cs[\"factor_raw\"])\n    cs[\"f_z\"] = zscore(cs[\"f_w\"])\n    cs[\"f_n\"] = zscore(neutralize(cs[\"f_z\"], cs[\"industry\"], cs[\"log_mcap\"]))\n\n    def describe(s):\n        return f\"min={s.min():7.2f} max={s.max():7.2f} 偏度={s.skew():6.2f} 与市值相关={s.corr(cs['log_mcap']):5.2f}\"\n    print(\"原始因子    \", describe(cs[\"factor_raw\"]))\n    print(\"去极值后    \", describe(cs[\"f_w\"]))\n    print(\"标准化后    \", describe(cs[\"f_z\"]))\n    print(\"中性化后    \", describe(cs[\"f_n\"]))\n    # 中性化后,各行业的因子均值应接近 0\n    print(\"中性化后各行业均值(前 5 个):\", cs.groupby(\"industry\")[\"f_n\"].mean().round(3).head().tolist())\n", "ch2_sim": "\"\"\"ch2_sim.py —— 生成一个“教学用”模拟股票面板。所有数据均为随机生成,不对应任何真实股票。\"\"\"\nimport numpy as np\nimport pandas as pd\n\ndef make_panel(n_stocks=500, n_months=72, n_ind=10, ic_true=0.03, persist=0.8, seed=7):\n    rng = np.random.default_rng(seed)\n    codes = [f\"S{i:04d}\" for i in range(n_stocks)]\n    months = pd.period_range(\"2019-01\", periods=n_months, freq=\"M\")\n    industry = rng.integers(0, n_ind, n_stocks)                  # 每只股票固定属于一个行业\n    log_mcap0 = rng.normal(23, 1.0, n_stocks)                    # 对数市值(约 1e10 元量级)\n    alpha = rng.standard_normal(n_stocks)                        # 真实“好坏”信号(不可直接观测)\n    alpha2 = rng.standard_normal(n_stocks)                       # 另一个独立的、较弱的真实信号\n    rows = []\n    for t, m in enumerate(months):\n        # 真实信号随时间缓慢变化:persist 越高,信号越持久(因子换手越低)\n        alpha = persist * alpha + np.sqrt(1 - persist**2) * rng.standard_normal(n_stocks)\n        alpha2 = persist * alpha2 + np.sqrt(1 - persist**2) * rng.standard_normal(n_stocks)\n        log_mcap = log_mcap0 + 0.05 * rng.standard_normal(n_stocks)\n        size_z = (log_mcap - log_mcap.mean()) / log_mcap.std()\n        # 我们观测到的“原始因子” = 真实信号 + 市值暴露 + 噪声,并混入少量极端值\n        raw = alpha + 0.8 * size_z + 0.7 * rng.standard_normal(n_stocks)\n        raw = np.where(rng.random(n_stocks) < 0.01, raw * 15, raw)       # 1% 的脏数据/极端值\n        # 第二个因子:主要反映 alpha2,并带一点 alpha 的成分和更多噪声\n        raw2 = alpha2 + 0.3 * alpha + 1.0 * rng.standard_normal(n_stocks)\n        # 下月收益 = 行业效应 + 小市值效应 + 真实 alpha + 特质噪声(月度)\n        ind_ret = rng.normal(0, 0.04, n_ind)[industry]\n        noise_sd = 0.10\n        fwd_ret = ind_ret - 0.01 * size_z + ic_true * noise_sd * (alpha + 0.7 * alpha2) + noise_sd * rng.standard_normal(n_stocks)\n        rows.append(pd.DataFrame({\"month\": m, \"code\": codes, \"industry\": industry,\n                                  \"log_mcap\": log_mcap, \"factor_raw\": raw, \"factor2_raw\": raw2, \"fwd_ret\": fwd_ret}))\n    return pd.concat(rows, ignore_index=True)\n", "ch3_adf": "import numpy as np\nfrom statsmodels.tsa.stattools import adfuller\n\nrng = np.random.default_rng(1)\nn = 1000\neps = rng.standard_normal(n)\n\nrandom_walk = np.cumsum(eps)                  # 随机游走:x_t = x_{t-1} + ε_t(单位根,非平稳)\nar1 = np.zeros(n)                             # AR(1):x_t = 0.9·x_{t-1} + ε_t(平稳)\nfor t in range(1, n):\n    ar1[t] = 0.9 * ar1[t - 1] + eps[t]\nlog_price = 4.6 + np.cumsum(0.0003 + 0.015 * rng.standard_normal(n))  # 模拟对数价格:带漂移的随机游走\nlog_ret = np.diff(log_price)                  # 对数收益率 = 对数价格的一阶差分\n\nfor name, x in [(\"随机游走\", random_walk), (\"AR(1) φ=0.9\", ar1),\n                (\"模拟对数价格\", log_price), (\"模拟对数收益率\", log_ret)]:\n    res = adfuller(x, autolag=\"AIC\")          # 自动用 AIC 选择差分滞后阶数\n    stat, pvalue, crit = res[0], res[1], res[4]   # 检验统计量、p 值、临界值字典\n    verdict = \"拒绝单位根 → 平稳\" if pvalue < 0.05 else \"不能拒绝单位根 → 视为非平稳\"\n    print(f\"{name:12s} ADF统计量={stat:7.3f}  p值={pvalue:.4f}  5%临界值={crit['5%']:.3f}  {verdict}\")\n", "ch3_arima": "import numpy as np\nfrom statsmodels.tsa.arima.model import ARIMA\nfrom statsmodels.stats.diagnostic import acorr_ljungbox\n\nrng = np.random.default_rng(2)\nn, mu, phi, sigma = 1500, 0.0003, 0.10, 0.012       # 真实参数:均值、AR 系数、噪声标准差\nr = np.zeros(n)\nfor t in range(1, n):                               # 生成 AR(1) 收益率:r_t − μ = φ(r_{t-1} − μ) + ε_t\n    r[t] = mu + phi * (r[t - 1] - mu) + sigma * rng.standard_normal()\n\nmodel = ARIMA(r, order=(1, 0, 0))                   # (p, d, q) = (1, 0, 0):AR(1),不差分,无 MA 项\nres = model.fit()\nconst, ar_l1, s2 = res.params                       # 估计的常数(=均值)、AR 系数、残差方差\nprint(f\"估计 μ={const:.5f}  φ={ar_l1:.3f} (标准误 {res.bse[1]:.3f})  σ={np.sqrt(s2):.4f}\")\nprint(f\"AIC={res.aic:.1f}\")\n\nlb = acorr_ljungbox(res.resid, lags=[10])           # 残差还有没有自相关?p 值大 = 没有明显剩余结构\nprint(f\"残差 Ljung-Box(10) p值={lb['lb_pvalue'].iloc[0]:.3f}\")\n\nfc = res.get_forecast(steps=3)                      # 向前预测 3 步\nprint(\"未来 3 天预测均值:\", np.round(fc.predicted_mean, 5))\nprint(\"95% 区间下限:\", np.round(fc.conf_int()[:, 0], 4))\n", "ch3_coint": "import numpy as np\nimport statsmodels.api as sm\nfrom statsmodels.tsa.stattools import coint, adfuller\n\nrng = np.random.default_rng(4)\nn = 750\n# 共同的随机趋势 + 各自的平稳偏离 → 两个价格序列协整(模拟数据)\ncommon = np.cumsum(rng.normal(0, 1, n))\nspread_true = np.zeros(n)\nfor t in range(1, n):                                  # 价差服从 AR(1),φ=0.95,会回归\n    spread_true[t] = 0.95 * spread_true[t - 1] + rng.normal(0, 1)\nx = 50 + common                                        # 资产 X\ny = 10 + 1.5 * x + spread_true                         # 资产 Y = 常数 + 1.5·X + 平稳价差\n\n# 第 1 步:OLS 回归 y = c + β·x,得到对冲比率 β\nols = sm.OLS(y, sm.add_constant(x)).fit()\nc_hat, beta_hat = ols.params\nspread = y - c_hat - beta_hat * x\nprint(f\"对冲比率 β 估计={beta_hat:.3f}  (真实 1.5)\")\n\n# 第 2 步:检验残差(价差)是否平稳 —— 用 coint() 而不是直接 adfuller(),\n# 因为残差是“估计出来的”,临界值需要用 Engle-Granger 专门的表\nt_stat, p_value, crit = coint(y, x)\nprint(f\"Engle-Granger 检验: 统计量={t_stat:.3f}  p值={p_value:.4f}  5%临界值={crit[1]:.3f}\")\nprint(f\"(对照)直接对价差做 ADF 的 p 值={adfuller(spread)[1]:.4f} —— 偏乐观,不应这样用\")\n\n# 第 3 步:均值回归半衰期:Δs_t = λ·s_{t-1} + 误差,半衰期 = −ln2 / λ\nds, s_lag = np.diff(spread), spread[:-1]\nlam = sm.OLS(ds, sm.add_constant(s_lag)).fit().params[1]\nprint(f\"λ={lam:.4f}  半衰期≈{-np.log(2)/lam:.1f} 天  (真实 φ=0.95 对应 {np.log(0.5)/np.log(0.95):.1f} 天)\")\n\n# 第 4 步:z-score 信号\nz = (spread - spread.mean()) / spread.std()\nprint(f\"|z|>2 的天数占比: {(np.abs(z) > 2).mean():.1%}\")\n", "ch3_garch": "import numpy as np\nfrom scipy.optimize import minimize\n\nrng = np.random.default_rng(3)\n# ---- 1) 用已知参数模拟一条 GARCH(1,1) 日收益率序列 ----\nomega, alpha, beta, n = 2e-6, 0.08, 0.90, 3000\nr, s2 = np.zeros(n), np.zeros(n)\ns2[0] = omega / (1 - alpha - beta)                 # 从长期方差开始\nfor t in range(n):\n    if t > 0:\n        s2[t] = omega + alpha * r[t - 1]**2 + beta * s2[t - 1]   # 条件方差递推\n    r[t] = np.sqrt(s2[t]) * rng.standard_normal()                 # 收益 = 条件波动 × 标准正态\n\n# ---- 2) 极大似然估计:最小化负对数似然 ----\ndef neg_loglik(params, r):\n    w, a, b = params\n    if w <= 0 or a < 0 or b < 0 or a + b >= 1:     # 不满足约束 → 返回极大值,让优化器避开\n        return 1e10\n    var = np.empty_like(r)\n    var[0] = r.var()                               # 初值:用样本方差\n    for t in range(1, len(r)):\n        var[t] = w + a * r[t - 1]**2 + b * var[t - 1]\n    return 0.5 * np.sum(np.log(2 * np.pi) + np.log(var) + r**2 / var)\n\nx0 = [r.var() * 0.05, 0.05, 0.90]                  # 合理的初始猜测\nopt = minimize(neg_loglik, x0, args=(r,), method=\"Nelder-Mead\",\n               options={\"maxiter\": 4000, \"xatol\": 1e-10, \"fatol\": 1e-6})\nw_hat, a_hat, b_hat = opt.x\nprint(f\"真实: ω={omega:.2e} α={alpha:.3f} β={beta:.3f}\")\nprint(f\"估计: ω={w_hat:.2e} α={a_hat:.3f} β={b_hat:.3f}  α+β={a_hat+b_hat:.3f}\")\nlong_run_vol = np.sqrt(w_hat / (1 - a_hat - b_hat) * 252)\nprint(f\"长期年化波动率≈{long_run_vol:.1%}  (真实值 {np.sqrt(omega/(1-alpha-beta)*252):.1%})\")\nhalf_life = np.log(0.5) / np.log(a_hat + b_hat)\nprint(f\"波动冲击半衰期≈{half_life:.1f} 个交易日\")\n\n# ---- 3) 向前预测:h 步后的方差向长期方差回归 ----\nvar_f = np.empty_like(r)                            # 用“估计出的参数”重新滤波得到条件方差序列\nvar_f[0] = r.var()\nfor t in range(1, n):\n    var_f[t] = w_hat + a_hat * r[t - 1]**2 + b_hat * var_f[t - 1]\nvar_T = w_hat + a_hat * r[-1]**2 + b_hat * var_f[-1]   # 明天(T+1)的条件方差\nlr_var = w_hat / (1 - a_hat - b_hat)\nfor h in [1, 5, 20, 60]:\n    v = lr_var + (a_hat + b_hat)**(h - 1) * (var_T - lr_var)\n    print(f\"{h:3d} 天后的日波动率预测: {np.sqrt(v):.4%}\")\n", "ch3_kalman": "import numpy as np\n\nrng = np.random.default_rng(5)\nn = 600\n# 真实对冲比率 β_t 随时间缓慢漂移(模拟数据)\nbeta_true = 1.0 + np.cumsum(rng.normal(0.001, 0.01, n))\nx = 50 + np.cumsum(rng.normal(0, 1, n))\ny = beta_true * x + rng.normal(0, 2.0, n)              # 观测:y_t = β_t·x_t + 观测噪声\n\n# 状态空间模型:\n#   状态方程 β_t = β_{t-1} + w_t,  w_t ~ N(0, Q)   (β 像随机游走一样慢慢变)\n#   观测方程 y_t = x_t·β_t + v_t,   v_t ~ N(0, R)\nQ, R = 1e-4, 4.0                                        # 过程噪声方差 / 观测噪声方差(需调参)\nbeta_hat, P = 0.0, 1.0                                  # 初始估计与其不确定性(方差)\nest = np.zeros(n)\nfor t in range(n):\n    # 1) 预测:β 的最佳猜测不变,不确定性增加 Q\n    P = P + Q\n    # 2) 更新:看到 y_t 后,用“预测误差”修正\n    y_pred = x[t] * beta_hat                            # 预测的观测值\n    err = y[t] - y_pred                                 # 新息(innovation)\n    S = x[t] * P * x[t] + R                             # 新息的方差\n    K = P * x[t] / S                                    # 卡尔曼增益:多相信新数据还是旧估计\n    beta_hat = beta_hat + K * err\n    P = (1 - K * x[t]) * P\n    est[t] = beta_hat\n\nols_beta = (x @ y) / (x @ x)                            # 对比:全样本一个固定 β(无截距)\nfor t in [50, 200, 400, 599]:\n    print(f\"t={t:3d}  真实β={beta_true[t]:.3f}  卡尔曼估计={est[t]:.3f}\")\nprint(f\"全样本 OLS 固定 β={ols_beta:.3f}\")\nprint(f\"后 400 天平均绝对误差: 卡尔曼={np.abs(est[200:]-beta_true[200:]).mean():.3f}  \"\n      f\"固定OLS={np.abs(ols_beta-beta_true[200:]).mean():.3f}\")\n", "ch4_bl": "import numpy as np\n\nnames = [\"股票A\", \"股票B\", \"债券C\", \"商品D\"]\nvol = np.array([0.20, 0.25, 0.05, 0.18])\ncorr = np.array([[1.0, 0.6, 0.1, 0.3], [0.6, 1.0, 0.0, 0.3],\n                 [0.1, 0.0, 1.0, 0.0], [0.3, 0.3, 0.0, 1.0]])\nSigma = np.outer(vol, vol) * corr\nw_mkt = np.array([0.35, 0.25, 0.30, 0.10])          # 假设的“市场/基准”权重\ndelta = 2.5                                          # 风险厌恶系数(常见取值 2~4,这里取 2.5)\ntau = 0.05                                           # 先验不确定性缩放\n\n# 1) 反推隐含均衡收益:π = δ Σ w_mkt(“市场持有这些权重,说明它隐含了这样的预期收益”)\npi = delta * Sigma @ w_mkt\n# 2) 观点:① 股票B 比 股票A 年化多 3%;② 商品D 年化收益 4%\nP = np.array([[-1, 1, 0, 0],\n              [0, 0, 0, 1]], dtype=float)\nQ = np.array([0.03, 0.04])\nOmega = np.diag(np.diag(P @ (tau * Sigma) @ P.T))    # 观点不确定性(He-Litterman 常用设定)\n# 3) 后验预期收益:\n#    μ_BL = [(τΣ)^{-1} + Pᵀ Ω^{-1} P]^{-1} [(τΣ)^{-1} π + Pᵀ Ω^{-1} Q]\nA = np.linalg.inv(tau * Sigma) + P.T @ np.linalg.inv(Omega) @ P\nb = np.linalg.inv(tau * Sigma) @ pi + P.T @ np.linalg.inv(Omega) @ Q\nmu_bl = np.linalg.solve(A, b)\n# 4) 用后验收益做无约束均值-方差:w = (δΣ)^{-1} μ_BL\nw_bl = np.linalg.solve(delta * Sigma, mu_bl)\nfor i, n in enumerate(names):\n    print(f\"{n}: 均衡收益 π={pi[i]:6.2%}  后验 μ_BL={mu_bl[i]:6.2%}  市场权重={w_mkt[i]:5.1%} → BL权重={w_bl[i]:6.1%}\")\nprint(f\"BL 权重合计={w_bl.sum():.3f}\")\n", "ch4_cvx": "import numpy as np\nimport cvxpy as cp\n\nrng = np.random.default_rng(9)\nN = 30                                              # 30 只虚构股票\nalpha = rng.normal(0, 0.02, N)                      # 模型给出的预期超额收益(模拟)\nB = rng.normal(1, 0.3, (N, 1))                      # 单因子暴露\nSigma = B @ B.T * 0.15**2 + np.diag(rng.uniform(0.2, 0.4, N)**2)   # 年化协方差\nindustry = rng.integers(0, 3, N)                    # 3 个行业\nw_bench = np.ones(N) / N                            # 基准:等权\nw_prev = w_bench.copy()                             # 上期持仓\nlam, tc = 5.0, 0.002                                # 风险厌恶、单边成本\n\nw = cp.Variable(N)\nactive = w - w_bench                                # 主动权重\nobjective = cp.Maximize(alpha @ w\n                        - lam * cp.quad_form(active, Sigma)        # 跟踪误差惩罚\n                        - tc * cp.norm1(w - w_prev))               # 交易成本惩罚(换手)\ncons = [cp.sum(w) == 1, w >= 0, w <= 0.08,                         # 满仓、只做多、个股上限 8%\n        cp.norm1(w - w_prev) <= 0.4]                               # 单期双边换手 ≤ 40%\nfor g in range(3):                                                 # 行业偏离基准不超过 ±5%\n    m = (industry == g).astype(float)\n    cons += [cp.abs(m @ active) <= 0.05]\nprob = cp.Problem(objective, cons)\nprob.solve()\nwv = w.value\nte = np.sqrt((wv - w_bench) @ Sigma @ (wv - w_bench))\nprint(f\"求解状态: {prob.status}\")\nprint(f\"持股数(权重>0.1%): {(wv > 1e-3).sum()}  最大权重: {wv.max():.2%}  换手: {np.abs(wv - w_prev).sum():.2%}\")\nprint(f\"预期超额收益: {alpha @ (wv - w_bench):.2%}  年化跟踪误差: {te:.2%}\")\nprint(\"行业偏离:\", [round(float(((industry == g) * (wv - w_bench)).sum()), 4) for g in range(3)])\n", "ch4_hrp": "import numpy as np\nimport pandas as pd\nfrom scipy.cluster.hierarchy import linkage, leaves_list\nfrom scipy.spatial.distance import squareform\n\nrng = np.random.default_rng(8)\n# 模拟 8 个资产:两个“板块”(各 4 个),板块内相关高 —— 教学用\nT, k = 500, 4\nf1, f2 = rng.standard_normal(T), rng.standard_normal(T)\nX = np.column_stack([0.8 * f1 + 0.6 * rng.standard_normal(T) for _ in range(k)] +\n                    [0.7 * f2 + 0.7 * rng.standard_normal(T) for _ in range(k)])\nX *= np.array([0.01, 0.012, 0.015, 0.02, 0.008, 0.01, 0.006, 0.009])   # 不同波动\nret = pd.DataFrame(X, columns=[f\"A{i}\" for i in range(8)])\ncov, corr = ret.cov(), ret.corr()\n\n# 第 1 步:树形聚类。距离 d_ij = sqrt((1 − ρ_ij)/2),相关越高距离越近\ndist = np.sqrt((1 - corr) / 2)\nlink = linkage(squareform(dist.values, checks=False), method=\"single\")\n# 第 2 步:准对角化 —— 按聚类树的叶子顺序重排资产,相似资产排在一起\norder = list(corr.index[leaves_list(link)])\n\ndef cluster_var(cov, items):\n    \"\"\"一个簇的方差:簇内用反方差权重组合后的方差。\"\"\"\n    c = cov.loc[items, items]\n    ivp = 1 / np.diag(c); ivp /= ivp.sum()\n    return ivp @ c.values @ ivp\n\n# 第 3 步:递归二分 —— 每次把列表劈成两半,按两半的风险反比分配权重\nw = pd.Series(1.0, index=order)\nclusters = [order]\nwhile clusters:\n    clusters = [c[j:k] for c in clusters for j, k in ((0, len(c)//2), (len(c)//2, len(c))) if len(c) > 1]\n    for i in range(0, len(clusters), 2):\n        left, right = clusters[i], clusters[i + 1]\n        vl, vr = cluster_var(cov, left), cluster_var(cov, right)\n        a = 1 - vl / (vl + vr)                       # 风险小的那半拿更多权重\n        w[left] *= a\n        w[right] *= 1 - a\nprint(\"聚类后的资产顺序:\", order)\nprint(\"HRP 权重:\", w.reindex(ret.columns).round(3).to_dict())\nprint(\"权重合计:\", round(w.sum(), 6))\n", "ch4_lw": "import numpy as np\nfrom sklearn.covariance import LedoitWolf\n\nrng = np.random.default_rng(6)\nN, T_train, T_test, trials = 50, 60, 250, 200   # 50 只资产,只有 60 个样本估计协方差\n# 真实协方差:单因子结构(市场 β)+ 特质波动 —— 模拟设定\nbeta = rng.uniform(0.5, 1.5, N)\nSigma_true = np.outer(beta, beta) * 0.01**2 + np.diag(rng.uniform(0.01, 0.03, N)**2)\nL = np.linalg.cholesky(Sigma_true)\n\ndef gmv(S):\n    \"\"\"全局最小方差权重(允许做空)。\"\"\"\n    x = np.linalg.solve(S, np.ones(len(S)))\n    return x / x.sum()\n\nres = {\"样本协方差\": [], \"Ledoit-Wolf\": [], \"真实协方差(理想)\": []}\nfor _ in range(trials):\n    X = rng.standard_normal((T_train, N)) @ L.T          # 训练期收益\n    S_sample = np.cov(X, rowvar=False)\n    S_lw = LedoitWolf().fit(X).covariance_               # 收缩估计\n    for k, S in [(\"样本协方差\", S_sample), (\"Ledoit-Wolf\", S_lw), (\"真实协方差(理想)\", Sigma_true)]:\n        w = gmv(S)\n        res[k].append(np.sqrt(w @ Sigma_true @ w) * np.sqrt(252))   # 组合真实的(样本外)年化波动\n\nlw = LedoitWolf().fit(rng.standard_normal((T_train, N)) @ L.T)\nprint(f\"一次拟合中 Ledoit-Wolf 收缩强度 δ={lw.shrinkage_:.2f}\")\nprint(f\"样本协方差条件数≈{np.linalg.cond(np.cov(rng.standard_normal((T_train, N)) @ L.T, rowvar=False)):.0f}\")\nfor k, v in res.items():\n    print(f\"{k:14s} 最小方差组合的真实年化波动: 均值={np.mean(v):.2%}  最差={np.max(v):.2%}\")\n", "ch4_mv": "import numpy as np\nimport cvxpy as cp\n\n# 4 个虚构资产的“假设”年化预期收益、波动率和相关系数(教学用,非真实市场数据)\nnames = [\"股票A\", \"股票B\", \"债券C\", \"商品D\"]\nmu = np.array([0.08, 0.10, 0.03, 0.06])\nvol = np.array([0.20, 0.25, 0.05, 0.18])\ncorr = np.array([[1.0, 0.6, 0.1, 0.3],\n                 [0.6, 1.0, 0.0, 0.3],\n                 [0.1, 0.0, 1.0, 0.0],\n                 [0.3, 0.3, 0.0, 1.0]])\nSigma = np.outer(vol, vol) * corr                  # 协方差 = σ_i σ_j ρ_ij\nones = np.ones(len(mu))\nSi = np.linalg.inv(Sigma)                           # Σ^{-1}\nrf = 0.02                                           # 无风险利率\n\n# 1) 全局最小方差组合(允许做空):w = Σ^{-1}1 / (1ᵀΣ^{-1}1)\nw_gmv = Si @ ones / (ones @ Si @ ones)\n# 2) 切点组合 / 最大夏普(允许做空):w ∝ Σ^{-1}(μ − rf)\nw_tan = Si @ (mu - rf); w_tan /= w_tan.sum()\n\ndef show(name, w):\n    r, s = w @ mu, np.sqrt(w @ Sigma @ w)\n    print(f\"{name:10s} 权重=\" + \" \".join(f\"{n}:{x:6.1%}\" for n, x in zip(names, w)) +\n          f\" | 收益={r:.2%} 波动={s:.2%} 夏普={(r-rf)/s:.2f}\")\nshow(\"最小方差\", w_gmv)\nshow(\"最大夏普\", w_tan)\nshow(\"等权\", ones / 4)\n\n# 3) 只做多 + 单资产不超过 50% 的最大夏普:用 cvxpy 求“给定收益下最小方差”,在收益网格上扫描\nw = cp.Variable(4)\ntarget = cp.Parameter()\nprob = cp.Problem(cp.Minimize(cp.quad_form(w, Sigma)),\n                  [cp.sum(w) == 1, w >= 0, w <= 0.5, mu @ w >= target])\nbest = None\nfor tr in np.linspace(0.03, 0.09, 61):              # 有效前沿:每个目标收益求一次\n    target.value = tr\n    prob.solve()\n    if w.value is None:                              # 目标收益不可达时跳过\n        continue\n    wv = np.clip(w.value, 0, None); wv /= wv.sum()\n    sr = (wv @ mu - rf) / np.sqrt(wv @ Sigma @ wv)\n    if best is None or sr > best[0]:\n        best = (sr, wv)\nshow(\"约束最大夏普\", best[1])\n", "ch4_rp": "import numpy as np\nfrom scipy.optimize import minimize\n\nvol = np.array([0.20, 0.25, 0.05, 0.18])            # 与 ch4_mv.py 同一组假设\ncorr = np.array([[1.0, 0.6, 0.1, 0.3], [0.6, 1.0, 0.0, 0.3],\n                 [0.1, 0.0, 1.0, 0.0], [0.3, 0.3, 0.0, 1.0]])\nSigma = np.outer(vol, vol) * corr\n\ndef risk_contrib(w, S):\n    \"\"\"风险贡献 RC_i = w_i (Σw)_i / σ_p,各项之和等于组合波动 σ_p。\"\"\"\n    sigma_p = np.sqrt(w @ S @ w)\n    return w * (S @ w) / sigma_p\n\ndef rp_objective(w, S):\n    rc = risk_contrib(w, S)\n    return np.sum((rc - rc.mean())**2)               # 让每个资产的风险贡献尽量相等\n\nn = len(vol)\nres = minimize(rp_objective, np.ones(n) / n, args=(Sigma,), method=\"SLSQP\",\n               bounds=[(0, 1)] * n, constraints=[{\"type\": \"eq\", \"fun\": lambda w: w.sum() - 1}],\n               options={\"ftol\": 1e-14})\nw_rp = res.x\nfor name, w in [(\"等权\", np.ones(n) / n), (\"风险平价\", w_rp), (\"反波动率\", (1/vol) / (1/vol).sum())]:\n    rc = risk_contrib(w, Sigma)\n    print(f\"{name:6s} 权重={np.round(w, 3)}  风险贡献占比={np.round(rc / rc.sum(), 3)}  组合波动={np.sqrt(w@Sigma@w):.2%}\")\n", "ch5_cv": "import numpy as np\nimport pandas as pd\nimport lightgbm as lgb\nfrom sklearn.model_selection import KFold\nfrom sklearn.metrics import accuracy_score\nfrom ch5_labels import make_prices, triple_barrier\n\nclose = make_prices()\ny, t1 = triple_barrier(close)\n\n# ---- 特征工程:全部只用“当天及以前”的数据 ----\nr = np.log(close).diff()\nX = pd.DataFrame({\n    \"ret_5\":   close.pct_change(5),                 # 过去 5 日收益\n    \"ret_20\":  close.pct_change(20),                # 过去 20 日收益(动量)\n    \"vol_20\":  r.rolling(20).std(),                 # 过去 20 日波动率\n    \"vol_60\":  r.rolling(60).std(),\n    \"ma_gap\":  close / close.rolling(60).mean() - 1,  # 价格偏离 60 日均线\n    \"z_20\":    (close - close.rolling(20).mean()) / close.rolling(20).std(),\n})\ndata = X.assign(y=y, t1=t1).dropna()\nXv, yv, t1v = data[X.columns], (data[\"y\"] > 0).astype(int), data[\"t1\"]\nprint(f\"样本数={len(data)}  正类比例={yv.mean():.1%}\")\n\ndef purged_kfold(index, t1, n_splits=5, embargo=0.01):\n    \"\"\"Purged K-Fold:按时间顺序切块;从训练集中删掉\n       (a) 标签区间 [t, t1] 与测试集区间重叠的样本(purge),\n       (b) 紧跟测试集之后一小段的样本(embargo)。\"\"\"\n    n = len(index); emb = int(n * embargo)\n    for test_idx in np.array_split(np.arange(n), n_splits):\n        t0, t_end = index[test_idx[0]], t1.iloc[test_idx].max()   # 测试集覆盖的时间范围\n        train_mask = np.ones(n, bool)\n        train_mask[test_idx] = False\n        overlap = (index <= t_end) & (t1.values >= t0)             # 标签区间与测试区间重叠\n        train_mask &= ~overlap\n        after = np.arange(test_idx[-1] + 1, min(n, test_idx[-1] + 1 + emb))\n        train_mask[after] = False                                   # embargo:测试集之后再空出一段\n        yield np.where(train_mask)[0], test_idx\n\ndef cv_score(splits):\n    accs = []\n    for tr, te in splits:\n        model = lgb.LGBMClassifier(n_estimators=200, learning_rate=0.05, num_leaves=15,\n                                   min_child_samples=20, subsample=0.8, subsample_freq=1,\n                                   colsample_bytree=0.8, random_state=0, verbose=-1)\n        model.fit(Xv.iloc[tr], yv.iloc[tr])\n        accs.append(accuracy_score(yv.iloc[te], model.predict(Xv.iloc[te])))\n    return np.mean(accs), np.std(accs)\n\nnaive = KFold(n_splits=5, shuffle=True, random_state=0).split(Xv)      # ❌ 打乱顺序的普通 K 折\nplain = KFold(n_splits=5, shuffle=False).split(Xv)                     # 按时间切块,但不 purge\npurged = purged_kfold(Xv.index, t1v, n_splits=5, embargo=0.01)         # ✅ purge + embargo\nprint(\"打乱的普通 KFold     准确率=%.3f ± %.3f\" % cv_score(naive))\nprint(\"按时间切块(未purge) 准确率=%.3f ± %.3f\" % cv_score(plain))\nprint(\"Purged + Embargo     准确率=%.3f ± %.3f\" % cv_score(purged))\nprint(\"(数据是无规律的模拟随机游走,真实可达的准确率约等于“总猜多数类”的水平:%.3f)\" % max(yv.mean(), 1 - yv.mean()))\n", "ch5_importance": "import numpy as np\nimport pandas as pd\nimport lightgbm as lgb\nfrom sklearn.inspection import permutation_importance\nfrom sklearn.metrics import roc_auc_score\n\nrng = np.random.default_rng(12)\nn = 4000\n# 模拟特征表:只有 f_signal1、f_signal2 真正有用,其余是纯噪声 —— 教学用\nX = pd.DataFrame({\n    \"f_signal1\": rng.standard_normal(n),\n    \"f_signal2\": rng.standard_normal(n),\n    \"noise_cont\": rng.standard_normal(n),            # 连续噪声:可切分点很多\n    \"noise_bin\": rng.integers(0, 2, n).astype(float),  # 二值噪声:只有一个切分点\n})\nlogit = 0.6 * X[\"f_signal1\"] - 0.4 * X[\"f_signal2\"]\ny = (rng.random(n) < 1 / (1 + np.exp(-logit))).astype(int)\n\nsplit = int(n * 0.7)                                  # 前 70% 训练、后 30% 测试(按顺序,不打乱)\nXtr, Xte, ytr, yte = X.iloc[:split], X.iloc[split:], y.iloc[:split], y.iloc[split:]\nmodel = lgb.LGBMClassifier(n_estimators=150, learning_rate=0.05, num_leaves=7, min_child_samples=50,\n                           random_state=0, verbose=-1).fit(Xtr, ytr)\n\nsplit_imp = pd.Series(model.booster_.feature_importance(\"split\"), index=X.columns)   # 被用来分裂的次数\ngain_imp = pd.Series(model.booster_.feature_importance(\"gain\"), index=X.columns)     # 分裂带来的总增益\nperm = permutation_importance(model, Xte, yte, n_repeats=20, random_state=0, scoring=\"roc_auc\")\nout = pd.DataFrame({\"split次数\": split_imp, \"gain占比\": gain_imp / gain_imp.sum(),\n                    \"置换重要性(测试集AUC下降)\": perm.importances_mean,\n                    \"置换重要性标准差\": perm.importances_std})\nprint(out.round(4).to_string())\nprint(f\"\\n测试集 AUC = {roc_auc_score(yte, model.predict_proba(Xte)[:, 1]):.3f}\")\n", "ch5_labels": "import numpy as np\nimport pandas as pd\n\ndef make_prices(n=2500, seed=11):\n    \"\"\"模拟日收盘价:带随机波动聚集的随机游走(没有可预测的规律)。\"\"\"\n    rng = np.random.default_rng(seed)\n    vol = np.empty(n); vol[0] = 0.015\n    for t in range(1, n):                       # 让波动率慢慢变化,更像真实行情\n        vol[t] = np.clip(vol[t-1] * np.exp(0.05 * rng.standard_normal()), 0.005, 0.05)\n    ret = vol * rng.standard_normal(n)\n    idx = pd.bdate_range(\"2015-01-01\", periods=n)\n    return pd.Series(100 * np.exp(np.cumsum(ret)), index=idx, name=\"close\")\n\ndef triple_barrier(close, horizon=10, k=2.0, vol_win=20):\n    \"\"\"三重障碍标签:\n       上障碍 = 入场价 × (1 + k·σ),下障碍 = 入场价 × (1 − k·σ),垂直障碍 = horizon 天后。\n       先碰上障碍 → +1;先碰下障碍 → −1;都没碰到 → 用到期时收益的符号。\n       返回标签和每个样本“标签结束时间” t1(后面做 purging 要用)。\"\"\"\n    sigma = close.pct_change().rolling(vol_win).std()      # 用过去 20 天波动率设定障碍宽度\n    labels, t1 = pd.Series(np.nan, index=close.index), pd.Series(pd.NaT, index=close.index)\n    for i in range(vol_win, len(close) - horizon):\n        p0, s = close.iloc[i], sigma.iloc[i]\n        path = close.iloc[i + 1:i + 1 + horizon] / p0 - 1  # 未来 horizon 天的累计收益路径\n        up = path[path >= k * s].index.min()               # 第一次触及上障碍的日期(没有则 NaT)\n        dn = path[path <= -k * s].index.min()\n        first = min([d for d in [up, dn] if pd.notna(d)], default=pd.NaT)\n        if pd.isna(first):                                 # 两条水平障碍都没碰到\n            labels.iloc[i], t1.iloc[i] = np.sign(path.iloc[-1]), path.index[-1]\n        else:\n            labels.iloc[i], t1.iloc[i] = (1 if first == up else -1), first\n    return labels, t1\n\nif __name__ == \"__main__\":\n    close = make_prices()\n    y, t1 = triple_barrier(close)\n    ok = y.dropna()\n    print(\"标签分布:\", ok.value_counts().sort_index().to_dict())\n    end_pos = close.index.get_indexer(t1.dropna())          # 标签结束日在序列中的位置\n    start_pos = close.index.get_indexer(t1.dropna().index)   # 入场日的位置\n    hold = end_pos - start_pos                                # 持有了多少个交易日\n    print(f\"平均持有 {hold.mean():.1f} 个交易日;  碰到垂直障碍(持满 10 天)的比例: {(hold == 10).mean():.0%}\")\n    print(ok.head(3).to_string())\n", "ch6_engine": "# >>> events\n\"\"\"ch6_engine.py —— 一个约 200 行的教学用事件驱动回测引擎。\n结构:DataHandler → Strategy → Portfolio → ExecutionHandler,模块之间只通过“事件”通信。\"\"\"\nfrom collections import deque\nfrom dataclasses import dataclass\nimport numpy as np\nimport pandas as pd\n\n@dataclass\nclass MarketEvent:            # 新的一根 K 线到了\n    date: pd.Timestamp\n\n@dataclass\nclass SignalEvent:            # 策略说:我想把某只股票的目标仓位调到 target(0~1,占总资产比例)\n    date: pd.Timestamp\n    symbol: str\n    target: float\n\n@dataclass\nclass OrderEvent:             # 组合说:请买/卖多少股\n    date: pd.Timestamp\n    symbol: str\n    qty: int                  # 正数买入、负数卖出\n\n@dataclass\nclass FillEvent:              # 撮合说:实际成交了多少、什么价、花了多少成本\n    date: pd.Timestamp\n    symbol: str\n    qty: int\n    price: float\n    cost: float\n# >>> data\nclass DataHandler:\n    \"\"\"按日期逐根推送 K 线。关键:策略只能通过 history() 拿到“当前及以前”的数据。\"\"\"\n    def __init__(self, bars: dict):                 # bars: {symbol: DataFrame[open, close, pre_close, volume]}\n        self.bars = bars\n        self.dates = sorted(set().union(*[df.index for df in bars.values()]))\n        self.i = -1\n    def update(self):\n        self.i += 1\n        return self.i < len(self.dates)             # 还有数据就返回 True\n    @property\n    def now(self):\n        return self.dates[self.i]\n    def history(self, symbol, field, n):\n        df = self.bars[symbol]\n        return df.loc[:self.now, field].iloc[-n:]   # 截至“现在”的最近 n 个值,杜绝未来函数\n    def next_bar(self, symbol):\n        \"\"\"下一根 K 线(只给撮合模块用,用来模拟“次日开盘成交”)。\"\"\"\n        df = self.bars[symbol]\n        pos = df.index.searchsorted(self.now, side=\"right\")\n        return df.iloc[pos] if pos < len(df) else None\n# >>> strategy\nclass MACrossStrategy:\n    \"\"\"双均线:短均线 > 长均线 → 目标仓位 = 1/股票数,否则 0。只在信号变化时发 SignalEvent。\"\"\"\n    def __init__(self, data, events, symbols, fast=10, slow=40):\n        self.data, self.events, self.symbols = data, events, symbols\n        self.fast, self.slow = fast, slow\n        self.state = {s: 0.0 for s in symbols}\n    def on_market(self, ev):\n        for s in self.symbols:\n            closes = self.data.history(s, \"close\", self.slow)\n            if len(closes) < self.slow:              # 数据不够计算长均线,先不动\n                continue\n            want = 1.0 / len(self.symbols) if closes.iloc[-self.fast:].mean() > closes.mean() else 0.0\n            if want != self.state[s]:\n                self.state[s] = want\n                self.events.append(SignalEvent(ev.date, s, want))\n# >>> portfolio\nclass Portfolio:\n    \"\"\"记账:现金、持仓、每日净值;把“目标仓位”翻译成“股数”(A 股按 100 股一手取整)。\"\"\"\n    def __init__(self, data, events, cash=1_000_000):\n        self.data, self.events = data, events\n        self.cash, self.pos = cash, {}\n        self.equity_curve, self.trades = [], []\n    def total_value(self):\n        mv = sum(q * self.data.history(s, \"close\", 1).iloc[-1] for s, q in self.pos.items())\n        return self.cash + mv\n    def on_signal(self, ev):\n        price = self.data.history(ev.symbol, \"close\", 1).iloc[-1]       # 用今天收盘价估算股数\n        target_qty = int(self.total_value() * ev.target / price // 100 * 100)\n        qty = target_qty - self.pos.get(ev.symbol, 0)\n        if qty != 0:\n            self.events.append(OrderEvent(ev.date, ev.symbol, qty))\n    def on_fill(self, ev):\n        self.pos[ev.symbol] = self.pos.get(ev.symbol, 0) + ev.qty\n        self.cash -= ev.qty * ev.price + ev.cost                         # 买入花钱、卖出收钱,成本总是扣\n        self.trades.append(ev)\n    def mark_to_market(self):\n        self.equity_curve.append((self.data.now, self.total_value()))\n# >>> execution\nclass SimExecution:\n    \"\"\"模拟撮合:次日开盘价成交 + 滑点;佣金(有最低 5 元)+ 卖出印花税;涨跌停/停牌不能成交。\n    费率为示意参数,请按你券商和交易所的实际规则修改。\"\"\"\n    def __init__(self, data, events, slippage_bps=5, commission=0.00025, min_comm=5.0,\n                 stamp_tax=0.0005, limit=0.10):\n        self.data, self.events = data, events\n        self.slip, self.comm, self.min_comm = slippage_bps / 1e4, commission, min_comm\n        self.tax, self.limit = stamp_tax, limit\n        self.rejected = 0\n    def on_order(self, ev):\n        bar = self.data.next_bar(ev.symbol)\n        if bar is None or bar[\"volume\"] <= 0:                           # 没有下一根或停牌\n            self.rejected += 1; return\n        up, down = bar[\"pre_close\"] * (1 + self.limit), bar[\"pre_close\"] * (1 - self.limit)\n        if (ev.qty > 0 and bar[\"open\"] >= up - 1e-9) or (ev.qty < 0 and bar[\"open\"] <= down + 1e-9):\n            self.rejected += 1; return                                  # 开盘涨停买不进 / 跌停卖不出\n        px = bar[\"open\"] * (1 + self.slip * np.sign(ev.qty))            # 滑点总是对自己不利\n        notional = abs(ev.qty) * px\n        cost = max(notional * self.comm, self.min_comm) + (notional * self.tax if ev.qty < 0 else 0)\n        self.events.append(FillEvent(bar.name, ev.symbol, ev.qty, px, cost))\n# >>> loop\ndef run_backtest(bars, **exec_kw):\n    events = deque()\n    data = DataHandler(bars)\n    strat = MACrossStrategy(data, events, list(bars))\n    port = Portfolio(data, events)\n    exe = SimExecution(data, events, **exec_kw)\n    while data.update():                         # 外层循环:时间前进一天\n        events.append(MarketEvent(data.now))\n        while events:                            # 内层循环:把今天产生的事件处理完\n            ev = events.popleft()\n            if isinstance(ev, MarketEvent):  strat.on_market(ev)\n            elif isinstance(ev, SignalEvent): port.on_signal(ev)\n            elif isinstance(ev, OrderEvent):  exe.on_order(ev)\n            elif isinstance(ev, FillEvent):   port.on_fill(ev)\n        port.mark_to_market()                    # 收盘后记录净值\n    eq = pd.Series(dict(port.equity_curve))\n    return eq, port, exe\n\ndef summary(eq):\n    r = eq.pct_change().dropna()\n    dd = eq / eq.cummax() - 1\n    return {\"总收益\": f\"{eq.iloc[-1]/eq.iloc[0]-1:.2%}\",\n            \"年化波动\": f\"{r.std()*np.sqrt(252):.2%}\",\n            \"夏普\": f\"{r.mean()/r.std()*np.sqrt(252):.2f}\",\n            \"最大回撤\": f\"{dd.min():.2%}\"}\n# >>> run\ndef make_bars(seed, n=750, mu=0.0003, sigma=0.02, p_suspend=0.01, limit=0.10):\n    \"\"\"模拟日 K 线(open/close/pre_close/volume):涨跌幅截断在 ±10%,约 1% 的交易日停牌。\n    纯教学用模拟数据,不对应任何真实股票。\"\"\"\n    rng = np.random.default_rng(seed)\n    idx = pd.bdate_range(\"2021-01-04\", periods=n)\n    rows, prev = [], 20.0\n    for t in range(n):\n        if rng.random() < p_suspend:                                   # 停牌:无成交,价格不变\n            rows.append((prev, prev, prev, 0)); continue\n        close = prev * np.exp(mu + sigma * rng.standard_normal())\n        close = min(max(close, prev * (1 - limit)), prev * (1 + limit))   # 涨跌停截断\n        opn = min(max(prev * (1 + 0.005 * rng.standard_normal()), prev * (1 - limit)), prev * (1 + limit))\n        rows.append((opn, close, prev, int(rng.integers(100_000, 1_000_000))))\n        prev = close\n    return pd.DataFrame(rows, columns=[\"open\", \"close\", \"pre_close\", \"volume\"], index=idx)\n\nif __name__ == \"__main__\":\n    bars = {f\"S{i}\": make_bars(seed=100 + i) for i in range(3)}\n    for name, kw in [(\"无成本\", dict(slippage_bps=0, commission=0, min_comm=0, stamp_tax=0)),\n                     (\"默认成本\", {}),\n                     (\"高滑点 30bp\", dict(slippage_bps=30))]:\n        eq, port, exe = run_backtest(bars, **kw)\n        fees = sum(f.cost for f in port.trades)                  # 显式费用:佣金 + 印花税(滑点已含在成交价里)\n        print(f\"{name:10s}\", summary(eq), f\"成交={len(port.trades)} 拒单={exe.rejected} 佣金+税={fees:,.0f} 元\")\n", "ch7_attribution": "import numpy as np\nimport statsmodels.api as sm\n\nrng = np.random.default_rng(25)\nT = 120                                                 # 10 年月度数据(全部为模拟)\nmkt = 0.006 + 0.045 * rng.standard_normal(T)            # 市场超额收益\nsmb = 0.002 + 0.030 * rng.standard_normal(T)            # 规模因子(小盘 − 大盘)\nmom = 0.004 + 0.035 * rng.standard_normal(T)            # 动量因子\n# “策略”的真实构成:0.9 倍市场 + 0.6 倍规模 + 很小的真实 alpha(每月 0.1%)+ 特质噪声\nstrat = 0.001 + 0.9 * mkt + 0.6 * smb + 0.0 * mom + 0.015 * rng.standard_normal(T)\n\nprint(f\"策略月均超额收益 = {strat.mean():.2%},年化 ≈ {strat.mean()*12:.1%}\")\n# 只对市场回归(CAPM):alpha 包含了规模暴露带来的收益\ncapm = sm.OLS(strat, sm.add_constant(mkt)).fit()\nprint(f\"CAPM:      alpha = {capm.params[0]:.2%}/月 (t = {capm.tvalues[0]:.2f}),  β_mkt = {capm.params[1]:.2f}\")\n# 多因子回归:把规模、动量也放进来\nX = sm.add_constant(np.column_stack([mkt, smb, mom]))\nff = sm.OLS(strat, X).fit()\na, b_mkt, b_smb, b_mom = ff.params\nprint(f\"三因子:    alpha = {a:.2%}/月 (t = {ff.tvalues[0]:.2f}),  β_mkt = {b_mkt:.2f}, β_smb = {b_smb:.2f}, β_mom = {b_mom:.2f}\")\nprint(f\"R² = {ff.rsquared:.2f}  —— 收益的大部分可以被已知因子解释\")\n# 收益分解:平均收益 = alpha + Σ β × 因子平均收益\nparts = {\"alpha\": a, \"市场\": b_mkt * mkt.mean(), \"规模\": b_smb * smb.mean(), \"动量\": b_mom * mom.mean()}\nprint(\"月均收益分解:\", {k: f\"{v:.3%}\" for k, v in parts.items()}, \" 合计:\", f\"{sum(parts.values()):.3%}\")\n", "ch7_multiple": "import numpy as np\nfrom scipy import stats\nfrom ch7_sharpe_stats import psr, expected_max_sr\n\nrng = np.random.default_rng(22)\nN, T = 200, 756                                   # 200 个策略,每个 3 年日度\nR = 0.01 * rng.standard_normal((T, N))            # 全部是纯噪声:真实夏普 = 0(模拟)\nsr = R.mean(0) / R.std(0, ddof=1)                 # 每期(日度)夏普\nsr_ann = sr * np.sqrt(252)\nbest = np.argmax(sr)\nprint(f\"最好的那个“策略”年化夏普 = {sr_ann[best]:.2f}  (而所有策略的真实夏普都是 0)\")\nprint(f\"年化夏普 > 1 的策略个数: {(sr_ann > 1).sum()} / {N}\")\n\n# 单个策略的 t 检验 p 值:H0 “均值收益 = 0”\nt = sr * np.sqrt(T)\np = 2 * (1 - stats.norm.cdf(np.abs(t)))\nprint(f\"未校正时 p<0.05 的个数: {(p < 0.05).sum()}  (理论上约 5% × {N} = {0.05*N:.0f} 个是“假阳性”)\")\nprint(f\"Bonferroni 校正 (p < 0.05/{N}) 后显著的个数: {(p < 0.05 / N).sum()}\")\n# Benjamini-Hochberg:控制错误发现率 FDR\norder = np.argsort(p); k = np.arange(1, N + 1)\npassed = p[order] <= 0.05 * k / N\nn_bh = k[passed].max() if passed.any() else 0\nprint(f\"BH(FDR=5%)显著的个数: {n_bh}\")\n# Deflated Sharpe:把“挑了 200 次”考虑进去\nsr0 = expected_max_sr(N, sr.var(ddof=1))\nprint(f\"200 次尝试下最大夏普的期望(年化)≈ {sr0*np.sqrt(252):.2f};  最好策略的 PSR(0)={psr(R[:, best]):.3f}  DSR={psr(R[:, best], sr0):.3f}\")\n", "ch7_pbo": "import numpy as np\nfrom itertools import combinations\n\ndef pbo_cscv(R, S=16):\n    \"\"\"CSCV 估计回测过拟合概率 PBO(Bailey, Borwein, López de Prado, Zhu)。\n    R: T×N 收益矩阵(N 个参数组合/策略)。把时间切成 S 块,枚举所有“一半块做样本内、另一半做样本外”的组合。\"\"\"\n    T, N = R.shape\n    blocks = np.array_split(np.arange(T), S)\n    logits = []\n    for is_idx in combinations(range(S), S // 2):\n        oos_idx = [b for b in range(S) if b not in is_idx]\n        IS = np.concatenate([blocks[b] for b in is_idx]); OOS = np.concatenate([blocks[b] for b in oos_idx])\n        sr_is = R[IS].mean(0) / R[IS].std(0)\n        sr_oos = R[OOS].mean(0) / R[OOS].std(0)\n        n_star = np.argmax(sr_is)                               # 样本内最好的那个\n        rank = (sr_oos < sr_oos[n_star]).sum() + 1              # 它在样本外的名次(1=最差)\n        w = rank / (N + 1)                                      # 相对名次 ∈ (0,1)\n        logits.append(np.log(w / (1 - w)))\n    logits = np.array(logits)\n    return (logits <= 0).mean(), len(logits)                    # 样本外跌到中位数以下的比例\n\nrng = np.random.default_rng(23)\nT, N = 1000, 50\nnoise = 0.01 * rng.standard_normal((T, N))                      # 情形 1:50 个纯噪声策略\npbo1, n_comb = pbo_cscv(noise)\nskill = noise.copy(); skill[:, :5] += 0.0015                     # 情形 2:其中 5 个有真实正收益(模拟)\npbo2, _ = pbo_cscv(skill)\nprint(f\"组合数 C(16,8) = {n_comb}\")\nprint(f\"纯噪声策略库:   PBO = {pbo1:.2f}\")\nprint(f\"含真实信号策略库: PBO = {pbo2:.2f}\")\n", "ch7_sharpe_stats": "import numpy as np\nfrom scipy import stats\n\ndef psr(returns, sr_benchmark=0.0):\n    \"\"\"Probabilistic Sharpe Ratio(Bailey & López de Prado):\n    在考虑样本长度、偏度、峰度后,真实夏普 > sr_benchmark 的概率。夏普用“每期”口径(不年化)。\"\"\"\n    r = np.asarray(returns)\n    T = len(r)\n    sr = r.mean() / r.std(ddof=1)\n    g3 = stats.skew(r)                              # 偏度\n    g4 = stats.kurtosis(r, fisher=False)            # 峰度(正态 = 3)\n    denom = np.sqrt(1 - g3 * sr + (g4 - 1) / 4 * sr**2)\n    return stats.norm.cdf((sr - sr_benchmark) * np.sqrt(T - 1) / denom)\n\ndef expected_max_sr(n_trials, var_sr):\n    \"\"\"在 n_trials 个“真实夏普都为 0”的策略中,样本夏普最大值的近似期望。\"\"\"\n    g = 0.5772156649                                # 欧拉-马歇罗尼常数\n    z1 = stats.norm.ppf(1 - 1 / n_trials)\n    z2 = stats.norm.ppf(1 - 1 / (n_trials * np.e))\n    return np.sqrt(var_sr) * ((1 - g) * z1 + g * z2)\n\ndef block_bootstrap_sharpe(r, block=20, n_boot=5000, seed=0):\n    \"\"\"移动块 bootstrap:整块(连续 block 天)地重抽样,保留收益的短期相关性。返回年化夏普的分布。\"\"\"\n    rng = np.random.default_rng(seed)\n    r = np.asarray(r); T = len(r)\n    n_blocks = int(np.ceil(T / block))\n    out = np.empty(n_boot)\n    for b in range(n_boot):\n        starts = rng.integers(0, T - block + 1, n_blocks)\n        sample = np.concatenate([r[s:s + block] for s in starts])[:T]\n        out[b] = sample.mean() / sample.std(ddof=1) * np.sqrt(252)\n    return out\n\nif __name__ == \"__main__\":\n    rng = np.random.default_rng(21)\n    T = 756                                                  # 3 年日度\n    r = 0.0004 + 0.01 * rng.standard_t(df=4, size=T) / np.sqrt(2)   # 模拟:带肥尾的日收益(t 分布)\n    sr_ann = r.mean() / r.std(ddof=1) * np.sqrt(252)\n    print(f\"样本年化夏普 = {sr_ann:.2f}\")\n    print(f\"偏度 = {stats.skew(r):.2f},  峰度 = {stats.kurtosis(r, fisher=False):.2f}(正态为 3)\")\n    boots = block_bootstrap_sharpe(r)\n    lo, hi = np.percentile(boots, [2.5, 97.5])\n    print(f\"块 bootstrap 95% 区间: [{lo:.2f}, {hi:.2f}],  夏普 ≤ 0 的 bootstrap 比例: {(boots <= 0).mean():.1%}\")\n    print(f\"PSR(基准 0) = {psr(r):.3f}\")\n    # 假设这个策略是从 100 个尝试里挑出来的最好的那个,各次尝试的(日度)夏普方差取 (0.5/√252)^2 —— 示意值\n    sr0 = expected_max_sr(100, (0.5 / np.sqrt(252))**2)\n    print(f\"100 次尝试下,纯靠运气的最大年化夏普期望 ≈ {sr0*np.sqrt(252):.2f}\")\n    print(f\"Deflated Sharpe Ratio = PSR(基准 = 该期望) = {psr(r, sr0):.3f}\")\n", "ch7_walkforward": "import numpy as np\nimport pandas as pd\n\nrng = np.random.default_rng(24)\nn = 252 * 8\n# 模拟价格:前半段有趋势性(收益正自相关),后半段没有 —— 模拟“市场环境变化”\neps = rng.standard_normal(n) * 0.012\nr = np.zeros(n)\nfor t in range(1, n):\n    phi = 0.08 if t < n // 2 else 0.0\n    r[t] = phi * r[t - 1] + eps[t]\nclose = pd.Series(100 * np.exp(np.cumsum(r)), index=pd.bdate_range(\"2016-01-01\", periods=n))\nret = close.pct_change().fillna(0)\n\ndef strat_returns(fast, slow, cost=0.0005):\n    \"\"\"均线策略日收益(信号滞后一天,扣单边成本)。\"\"\"\n    pos = (close.rolling(fast).mean() > close.rolling(slow).mean()).astype(float).shift(1).fillna(0)\n    return pos * ret - pos.diff().abs().fillna(0) * cost\n\ndef sharpe(x):\n    return x.mean() / x.std() * np.sqrt(252) if x.std() > 0 else 0.0\n\ngrid = [(f, s) for f in [5, 10, 20, 40] for s in [60, 120, 200] if f < s]\n# ---- 参数敏感性:全样本上每组参数的夏普(注意:这一步只用来“看地形”,不用来挑参数)----\ntable = pd.Series({g: sharpe(strat_returns(*g)) for g in grid}).unstack()\nprint(\"全样本夏普(行=短均线,列=长均线):\"); print(table.round(2).to_string())\n\n# ---- 滚动前向:每次用过去 3 年选参数,在接下来 1 年上测试,然后整体往前滚 1 年 ----\nall_r = {g: strat_returns(*g) for g in grid}\nyears = sorted(set(close.index.year))\noos = []\nfor k in range(3, len(years)):\n    train = close.index.year.isin(years[k - 3:k]); test = close.index.year == years[k]\n    best = max(grid, key=lambda g: sharpe(all_r[g][train]))\n    oos.append(all_r[best][test])\n    print(f\"训练 {years[k-3]}-{years[k-1]} → 选中 {best},  样本内夏普={sharpe(all_r[best][train]):.2f},  \"\n          f\"{years[k]} 年样本外夏普={sharpe(all_r[best][test]):.2f}\")\nprint(f\"拼接后的样本外夏普 = {sharpe(pd.concat(oos)):.2f}\")\n", "ch8_execution": "import numpy as np\n\nrng = np.random.default_rng(31)\n# ---- 1) 模拟一天的成交量分布:A 股连续竞价共 4 小时 = 240 分钟,这里按 48 个 5 分钟区间 ----\nk = np.arange(48)\nprofile = 1.0 + 1.5 * np.exp(-k / 4) + 1.2 * np.exp(-(47 - k) / 4)   # 早盘、尾盘量大的 U 形(示意)\nprofile[24:] *= 0.9                                                  # 下午略低(示意)\nprofile /= profile.sum()\nday_volume = 5_000_000                                               # 当天总成交量(股,假设)\nmarket_vol = rng.multinomial(day_volume, profile)                    # 每个区间的成交量(模拟)\n# 模拟价格:随机游走 + 我们自己的买单造成的临时冲击\nsigma_5m = 0.0015\nprice = 10 * np.exp(np.cumsum(sigma_5m * rng.standard_normal(48)))\n\nparent_qty = 250_000                                                 # 母单:要买 25 万股(占日成交 5%)\ntwap = np.full(48, parent_qty / 48)                                  # TWAP:时间均匀切分\nvwap = parent_qty * profile                                          # VWAP:按预测的成交量分布切分\n\ndef execute(schedule, eta=0.1):\n    \"\"\"临时冲击模型:每个区间的成交价 = 市场价 × (1 + η·σ·√(子单量/该区间成交量))。\"\"\"\n    part = schedule / market_vol                                     # 参与率\n    fill_px = price * (1 + eta * sigma_5m * 10 * np.sqrt(part))      # 系数为示意值\n    avg = (fill_px * schedule).sum() / schedule.sum()\n    return avg, part.max()\n\narrival = price[0]                                                   # 决策时(到达)价格\nmkt_vwap = (price * market_vol).sum() / market_vol.sum()             # 全市场当日 VWAP\nfor name, sch in [(\"TWAP\", twap), (\"VWAP\", vwap)]:\n    avg, pmax = execute(sch)\n    is_bp = (avg - arrival) / arrival * 1e4                          # 执行落差 Implementation Shortfall\n    vs_vwap = (avg - mkt_vwap) / mkt_vwap * 1e4\n    print(f\"{name}: 成交均价={avg:.4f}  执行落差={is_bp:6.1f} bp  相对市场VWAP={vs_vwap:5.1f} bp  最大参与率={pmax:.1%}\")\n\n# ---- 2) 平方根冲击模型的“量级估算”:成本 ≈ Y · σ_日 · √(Q / V_日) ----\nY, sigma_d = 1.0, 0.02                                               # Y 为经验系数(需用自己的成交数据校准)\nfor q_frac in [0.01, 0.05, 0.20]:\n    print(f\"下单量=日成交量的 {q_frac:4.0%}: 估算冲击 ≈ {Y*sigma_d*np.sqrt(q_frac)*1e4:5.1f} bp\")\n", "ch8_orderbook": "# 一个极简的限价订单簿(Limit Order Book)—— 数字均为虚构示例\nasks = [(10.02, 300), (10.03, 500), (10.04, 800), (10.05, 1200), (10.06, 2000)]   # 卖一 ~ 卖五 (价格, 股数)\nbids = [(10.00, 400), (9.99, 600), (9.98, 900), (9.97, 1500), (9.96, 2500)]       # 买一 ~ 买五\n\nbest_ask, best_bid = asks[0][0], bids[0][0]\nmid = (best_ask + best_bid) / 2                         # 中间价\nspread = best_ask - best_bid                            # 绝对价差\nprint(f\"买一={best_bid} 卖一={best_ask} 中间价={mid:.3f} 价差={spread:.2f} 元 = {spread/mid*1e4:.1f} bp\")\n\ndef market_buy(book, qty):\n    \"\"\"市价买入 qty 股:从卖一开始逐档“吃掉”挂单,直到买够。返回成交均价和成交明细。\"\"\"\n    left, cost, fills = qty, 0.0, []\n    for price, size in book:\n        take = min(left, size)\n        fills.append((price, take)); cost += price * take; left -= take\n        if left == 0:\n            break\n    if left > 0:\n        raise ValueError(\"五档深度不够,剩余 %d 股无法成交\" % left)\n    return cost / qty, fills\n\nfor q in [200, 1000, 3000]:\n    avg, fills = market_buy(asks, q)\n    slip_bp = (avg - mid) / mid * 1e4                   # 相对中间价的成本(bp)\n    print(f\"市价买 {q:5d} 股: 成交均价={avg:.4f}  相对中间价成本={slip_bp:5.1f} bp  吃到 {len(fills)} 档\")\n\n# 订单簿不平衡度:买一量与卖一量的相对大小,常被用作极短期价格方向的特征\nimb = (bids[0][1] - asks[0][1]) / (bids[0][1] + asks[0][1])\nprint(f\"一档不平衡度 = {imb:.2f}  (>0 表示买盘相对更厚)\")\n", "ch9_risk": "from dataclasses import dataclass, field\nimport numpy as np\n\n@dataclass\nclass RiskLimits:                       # 风控参数:全部是示意值,请根据自己的资金规模和策略设定\n    max_order_value: float = 200_000    # 单笔委托金额上限(元)\n    max_position_pct: float = 0.10      # 单只股票持仓占总资产上限\n    max_daily_orders: int = 200         # 每日委托笔数上限(防止程序死循环狂发单)\n    max_price_dev: float = 0.03         # 委托价偏离最新价上限(防“乌龙指”)\n    daily_loss_stop: float = 0.03       # 当日亏损达到 3% 停止开新仓\n    blacklist: set = field(default_factory=lambda: {\"ST_XYZ\"})\n\nclass PreTradeRisk:\n    \"\"\"事前风控:每一笔委托发出前都必须通过全部检查,任何一条不满足就拒绝并记录原因。\"\"\"\n    def __init__(self, limits: RiskLimits, equity: float):\n        self.lim, self.equity, self.start_equity = limits, equity, equity\n        self.orders_today, self.positions = 0, {}\n        self.kill_switch = False                                     # 人工或自动触发的“总开关”\n\n    def check(self, symbol, qty, price, last_price):\n        L = self.lim\n        value = abs(qty) * price\n        new_pos_value = (self.positions.get(symbol, 0) + qty) * last_price\n        rules = [\n            (self.kill_switch, \"总开关已关闭\"),\n            (symbol in L.blacklist, \"标的在黑名单\"),\n            (qty % 100 != 0 and qty > 0, \"买入数量不是 100 股整数倍\"),\n            (value > L.max_order_value, f\"单笔金额 {value:,.0f} 超过上限\"),\n            (abs(price / last_price - 1) > L.max_price_dev, \"委托价偏离最新价过大\"),\n            (new_pos_value > L.max_position_pct * self.equity, \"成交后单票仓位超限\"),\n            (self.orders_today >= L.max_daily_orders, \"当日委托笔数已达上限\"),\n            (qty > 0 and self.equity / self.start_equity - 1 <= -L.daily_loss_stop, \"当日亏损触发止损,禁止开仓\"),\n        ]\n        for hit, reason in rules:\n            if hit:\n                return False, reason\n        self.orders_today += 1\n        return True, \"通过\"\n\n    def on_fill(self, symbol, qty):\n        \"\"\"成交回报到达后更新持仓 —— 持仓以成交为准,而不是以“发出的委托”为准。\"\"\"\n        self.positions[symbol] = self.positions.get(symbol, 0) + qty\n\nrisk = PreTradeRisk(RiskLimits(), equity=1_000_000)\ntests = [(\"X0001\", 5000, 10.00, 10.00), (\"X0001\", 30000, 10.00, 10.00), (\"X0002\", 1000, 10.80, 10.00),\n         (\"ST_XYZ\", 100, 5.00, 5.00), (\"X0003\", 150, 20.00, 20.00), (\"X0004\", 8000, 12.00, 12.00),\n         (\"X0001\", 6000, 10.00, 10.00)]   # 最后一笔:X0001 已持有 5000 股,再买 6000 股将超过 10% 仓位上限\nfor t in tests:\n    ok, why = risk.check(*t)\n    if ok:\n        risk.on_fill(t[0], t[1])          # 演示:假设通过的委托全部成交\n    print(f\"{t[0]:7s} 数量={t[1]:6d} 价格={t[2]:6.2f} → {'✅' if ok else '❌'} {why}\")\n\n# ---- 事后监控:实盘净值相对回测净值的跟踪偏差,超阈值就告警 ----\nrng = np.random.default_rng(41)\nbt = np.cumprod(1 + 0.0005 + 0.01 * rng.standard_normal(60))              # 回测(模拟)\nlive = bt * np.cumprod(1 - 0.0004 + 0.002 * rng.standard_normal(60))      # 实盘 = 回测 × 额外损耗(模拟)\ngap = live / bt - 1\nalert_day = np.argmax(gap < -0.02) if (gap < -0.02).any() else None\nprint(f\"60 天后实盘相对回测偏差: {gap[-1]:.2%};  首次跌破 −2% 告警阈值: 第 {alert_day + 1 if alert_day is not None else '—'} 天\")\n", "pre_matrix": "import numpy as np\nw = np.array([0.6, 0.4])\nsigma = np.array([0.20, 0.10])\ncorr = np.array([[1.0, 0.3], [0.3, 1.0]])\nSigma = np.outer(sigma, sigma) * corr   # 协方差矩阵 = σ_i σ_j ρ_ij\nprint(w @ Sigma @ w)                    # 0.01888  —— @ 就是矩阵乘法\nprint(np.sqrt(w @ Sigma @ w))           # 0.1374...\n"};
window.PYEXTRA = {"ch1_parquet": ["pyarrow"], "ch2_ic": ["scipy"], "ch2_combine": ["scipy"]};
